    /// Builds a FROM clause consisting of one or more items.
    fn build_from_clause(&self, from: Vec<ast::From>, scope: &mut Scope) -> Result<Node> {
        if from.is_empty() {
            return Ok(Node::Scan {
                table: None,
                condition: None,
            });
        }

        let mut result = self.build_from(from[0].clone(), scope)?;

        for item in from.iter().skip(1) {
            let child_scope = scope.spawn();
            let child = self.build_from(item.clone(), &mut child_scope.clone())?;
            result = Node::Join {
                left: Box::new(result),
                right: Box::new(child),
                join_type: ast::JoinType::Inner,
                condition: None,
            };
            scope.merge(child_scope)?;
        }

        Ok(result)
    }

    /// Builds FROM items, which can either be a single table or a chained join
    /// of multiple tables.
    fn build_from(&self, from: ast::From, parent_scope: &mut Scope) -> Result<Node> {
        match from {
            ast::From::Table { name, alias } => {
                let table = self.catalog.get_table(&name).ok_or_else(|| errinput!("unknown table: {}", name))?;
                parent_scope.add_table(table, alias.as_deref())?;
                Ok(Node::Scan {
                    table: Some(name),
                    condition: None,
                })
            }
            ast::From::Join { left, right, r#type, predicate } => {
                let mut left_scope = parent_scope.spawn();
                let left_node = self.build_from(*left, &mut left_scope)?;

                let mut right_scope = left_scope.spawn();
                let right_node = self.build_from(*right, &mut right_scope)?;

                parent_scope.merge(left_scope)?;
                parent_scope.merge(right_scope)?;

                let condition = predicate.map(|e| Self::build_expression(e, parent_scope)).transpose()?;

                Ok(Node::Join {
                    left: Box::new(left_node),
                    right: Box::new(right_node),
                    join_type: r#type,
                    condition,
                })
            }
        }
    }

    /// Builds an aggregate node.
    fn build_aggregate(
        &self,
        source: Node,
        mut group_by: Vec<ast::Expression>,
        mut aggregates: Vec<ast::Expression>,
        scope: &mut Scope,
    ) -> Result<Node> {
        let group_by_expressions: Vec<Expression> = group_by
            .drain(..)
            .map(|e| Self::build_expression(e, scope))
            .collect::<Result<_>>()?;

        let aggregate_expressions: Vec<Expression> = aggregates
            .drain(..)
            .map(|e| Self::build_expression(e, scope))
            .collect::<Result<_>>()?;

        Ok(Node::Aggregate {
            source: Box::new(source),
            group_by: group_by_expressions,
            aggregates: aggregate_expressions,
        })
    }

    /// Builds an aggregate function from an AST expression.
    fn build_aggregate_function(expr: ast::Expression, scope: &Scope) -> Result<Aggregate> {
        if let ast::Expression::Operator(ast::Operator::Function(name, args)) = expr {
            let args: Vec<Expression> = args
                .into_iter()
                .map(|e| Self::build_expression(e, scope))
                .collect::<Result<_>>()?;

            match name.to_lowercase().as_str() {
                "count" => Ok(Aggregate::Count(args)),
                "sum" => Ok(Aggregate::Sum(args)),
                "avg" => Ok(Aggregate::Avg(args)),
                "min" => Ok(Aggregate::Min(args)),
                "max" => Ok(Aggregate::Max(args)),
                "group_concat" => Ok(Aggregate::GroupConcat(args)),
                _ => Err(errinput!("unknown aggregate function: {}", name)),
            }
        } else {
            Err(errinput!("expected aggregate function"))
        }
    }

    /// Checks whether a given AST expression is an aggregate function.
    fn is_aggregate_function(expr: &ast::Expression) -> bool {
        matches!(expr, ast::Expression::Operator(ast::Operator::Function(name, _)) if name.to_lowercase() == "count" || name.to_lowercase() == "sum" || name.to_lowercase() == "avg" || name.to_lowercase() == "min" || name.to_lowercase() == "max" || name.to_lowercase() == "group_concat")
    }

    /// Collects aggregate functions from SELECT, HAVING, and ORDER BY clauses.
    fn collect_aggregates(
        select: &[(ast::Expression, Option<String>)],
        having: &Option<ast::Expression>,
        order_by: &[(ast::Expression, ast::Direction)],
    ) -> Vec<ast::Expression> {
        let mut aggregates = Vec::new();
        for (expr, _) in select {
            if Self::is_aggregate_function(expr) {
                aggregates.push(expr.clone());
            }
        }
        if let Some(expr) = having {
            if Self::is_aggregate_function(expr) {
                aggregates.push(expr.clone());
            }
        }
        for (expr, _) in order_by {
            if Self::is_aggregate_function(expr) {
                aggregates.push(expr.clone());
            }
        }
        aggregates
    }

    /// Builds hidden columns for a projection to pass through columns that are
    /// used by downstream nodes.
    fn build_select_hidden(
        &self,
        having: &Option<ast::Expression>,
        order_by: &[(ast::Expression, ast::Direction)],
        scope: &Scope,
        child_scope: &mut Scope,
    ) -> Vec<Expression> {
        let mut hidden = Vec::new();

        if let Some(expr) = having {
            expr.collect(&mut |e| {
                if let ast::Expression::Column(table, name) = e {
                    if let Ok(idx) = scope.lookup_column(table.as_deref(), name) {
                        hidden.push(Self::build_expression(ast::Expression::Column(table.clone(), name.clone()), child_scope).unwrap());
                    }
                }
                true
            }, &mut Vec::new());
        }

        for (expr, _) in order_by {
            expr.collect(&mut |e| {
                if let ast::Expression::Column(table, name) = e {
                    if let Ok(idx) = scope.lookup_column(table.as_deref(), name) {
                        hidden.push(Self::build_expression(ast::Expression::Column(table.clone(), name.clone()), child_scope).unwrap());
                    }
                }
                true
            }, &mut Vec::new());
        }

        hidden
    }

    /// Builds an expression from an AST expression, looking up columns and
    /// aggregate expressions in the scope.
    pub fn build_expression(expr: ast::Expression, scope: &Scope) -> Result<Expression> {
        match expr {
            ast::Expression::All => Err(errinput!("cannot use * in expression")),
            ast::Expression::Column(table, name) => {
                let idx = scope.lookup_column(table.as_deref(), &name)?;
                Ok(Expression::Column(idx))
            }
            ast::Expression::Literal(lit) => {
                Ok(Expression::Literal(match lit {
                    ast::Literal::Null => Value::Null,
                    ast::Literal::Boolean(b) => Value::Boolean(b),
                    ast::Literal::Integer(i) => Value::Integer(i),
                    ast::Literal::Float(f) => Value::Float(f),
                    ast::Literal::String(s) => Value::String(s),
                }))
            }
            ast::Expression::Function(name, args) => {
                let args: Vec<Expression> = args
                    .into_iter()
                    .map(|e| Self::build_expression(e, scope))
                    .collect::<Result<_>>()?;
                Ok(Expression::Function(name, args))
            }
            ast::Expression::Operator(op) => {
                Self::build_operator(op, scope)
            }
        }
    }

    /// Builds a constant value from an AST expression by evaluating it.
    fn build_constant_value(expr: ast::Expression) -> Result<Value> {
        match expr {
            ast::Expression::Literal(lit) => Ok(match lit {
                ast::Literal::Null => Value::Null,
                ast::Literal::Boolean(b) => Value::Boolean(b),
                ast::Literal::Integer(i) => Value::Integer(i),
                ast::Literal::Float(f) => Value::Float(f),
                ast::Literal::String(s) => Value::String(s),
            }),
            _ => Err(errinput!("expected constant expression")),
        }
    }
